import { Router } from 'express';
import multer from 'multer';
import { randomUUID } from 'node:crypto';
import { v2 as cloudinary } from 'cloudinary';
import mongoose from 'mongoose';
import { z } from 'zod';
import { authenticate, allowRoles } from '../middleware/auth.js';
import { RecordModel } from '../models/Record.js';
import { User } from '../models/User.js';
import { SystemSetting } from '../models/SystemSetting.js';
import { env } from '../config/env.js';
import { destroyCloudinaryAsset } from '../services/cloudinaryCleanup.js';
import { audit } from '../services/audit.js';
import { notify, queueEmailUserIfEnabled } from '../services/notifications.js';

const router = Router();
router.use(authenticate);
const teachingRoles = ['LECTURER','LECTURER_HOD'] as const;
const lecturerDocumentTypes = ['cv','highest_degree_certificate','professional_certificate','identity_document'] as const;
type LecturerDocumentType = typeof lecturerDocumentTypes[number];
const lecturerDocumentLabels: Record<LecturerDocumentType,string> = {cv:'Curriculum Vitae (CV)',highest_degree_certificate:'Highest qualification certificate',professional_certificate:'Professional certificate',identity_document:'Identity document'};
const lecturerDocumentUpload = multer({storage:multer.memoryStorage(),limits:{fileSize:8*1024*1024,files:4},fileFilter:(_req,file,cb)=>{
  const allowed=['application/pdf','image/jpeg','image/png'];
  if(!lecturerDocumentTypes.includes(file.fieldname as LecturerDocumentType)||!allowed.includes(file.mimetype))return cb(new Error('Lecturer documents must be PDF, JPEG or PNG files, up to 8 MB each.'));
  cb(null,true);
}}).fields(lecturerDocumentTypes.map(name=>({name,maxCount:1})));
function configureLecturerCloudinary(){if(!env.cloudinaryCloudName||!env.cloudinaryApiKey||!env.cloudinaryApiSecret)throw Object.assign(new Error('Lecturer document storage is not configured. Set the Cloudinary server environment variables.'),{status:503});cloudinary.config({cloud_name:env.cloudinaryCloudName,api_key:env.cloudinaryApiKey,api_secret:env.cloudinaryApiSecret,secure:true});}
function sanitizeLecturerApplication(record:any){const plain=typeof record?.toObject==='function'?record.toObject():record;const data={...(plain?.data||{})};if(Array.isArray(data.documents))data.documents=data.documents.map((doc:any)=>({documentType:doc.documentType,label:doc.label,format:doc.format,bytes:doc.bytes,mimeType:doc.mimeType,uploadedAt:doc.uploadedAt}));return {...plain,data};}
function validFileSignature(file:Express.Multer.File){const b=file.buffer;if(file.mimetype==='application/pdf')return b.length>=5&&b.subarray(0,5).toString('ascii')==='%PDF-';if(file.mimetype==='image/jpeg')return b.length>=3&&b[0]===0xff&&b[1]===0xd8&&b[2]===0xff;if(file.mimetype==='image/png')return b.length>=8&&b.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10]));return false;}
function uploadLecturerDocument(file:Express.Multer.File,ownerId:string,applicationRef:string,type:LecturerDocumentType){configureLecturerCloudinary();const resourceType=file.mimetype==='application/pdf'?'raw':'image';const ext=file.mimetype==='application/pdf'?'pdf':file.mimetype==='image/png'?'png':'jpg';return new Promise<any>((resolve,reject)=>{const stream=cloudinary.uploader.upload_stream({folder:`crestfield/private-lecturer-applications/${ownerId}/${applicationRef}`,resource_type:resourceType,type:'authenticated',public_id:`${type}-${randomUUID()}`,format:ext,overwrite:false,context:{documentType:type,applicationReference:applicationRef}},(error,result)=>error||!result?reject(error||new Error('Cloudinary upload failed.')):resolve(result));stream.end(file.buffer);});}
const objectId = (v:string) => mongoose.isValidObjectId(v);
const isStudentRole = (role:string) => ['REGISTERED_STUDENT','STUDENT'].includes(role);

// Public-to-signed-in-user recruitment board. Vacancies are visible only after Super Admin publication.
router.get('/vacancies', async (_req,res,next) => {
  try {
    const vacancies = await RecordModel.find({module:'lecturer-recruitment', status:'PUBLISHED', 'data.kind':'lecturer-vacancy', 'data.closesAt':{$gt:new Date().toISOString()}}).sort({createdAt:-1}).limit(100).select('title status reference data createdAt').lean();
    res.json({vacancies});
  } catch(e){next(e);}
});

// Registrar creates/authorizes a vacancy. Super Admin alone publishes it.
router.post('/vacancies', allowRoles('REGISTRAR'), async (req,res,next) => {
  try {
    const b=z.object({title:z.string().trim().min(4).max(160),department:z.string().trim().min(2).max(120),faculty:z.string().trim().min(2).max(120),position:z.string().trim().min(2).max(100),qualifications:z.string().trim().min(10).max(4000),requirements:z.string().trim().min(10).max(4000),closesAt:z.string().datetime(),employmentType:z.enum(['FULL_TIME','PART_TIME','CONTRACT']).default('FULL_TIME'),initialRecruitmentMode:z.boolean().default(false)}).parse(req.body);
    if(new Date(b.closesAt).getTime()<=Date.now()) return res.status(400).json({message:'The vacancy closing date must be in the future.'});
    const record=await RecordModel.create({module:'lecturer-recruitment',title:b.title,status:'AUTHORIZED_FOR_PUBLICATION',reference:`LECT-VAC-${new Date().getFullYear()}-${new mongoose.Types.ObjectId().toString().slice(-8).toUpperCase()}`,data:{kind:'lecturer-vacancy',...b,authorizedBy:req.user!.id,authorizedAt:new Date().toISOString(),publishedAt:null,applicationsOpen:false},createdBy:req.user!.id,updatedBy:req.user!.id});
    await audit(req,'LECTURER_VACANCY_AUTHORIZED','lecturer-recruitment',record.id,{department:b.department,position:b.position});
    res.status(201).json({record,message:'Vacancy authorized by the Registrar. It is not public until the Super Admin publishes it.'});
  }catch(e){next(e);}
});
router.get('/vacancies/admin', allowRoles('SUPER_ADMIN','REGISTRAR'), async (_req,res,next)=>{
  try{const records=await RecordModel.find({module:'lecturer-recruitment','data.kind':'lecturer-vacancy'}).sort({createdAt:-1}).limit(200).lean();res.json({records});}catch(e){next(e);}
});
router.post('/vacancies/:id/publish', allowRoles('SUPER_ADMIN'), async(req,res,next)=>{
  try{
    if(!objectId(req.params.id))return res.status(400).json({message:'Invalid vacancy identifier.'});
    const r=await RecordModel.findOne({_id:req.params.id,module:'lecturer-recruitment','data.kind':'lecturer-vacancy'});
    if(!r)return res.status(404).json({message:'Authorized vacancy not found.'});
    if(r.status!=='AUTHORIZED_FOR_PUBLICATION')return res.status(409).json({message:'Only a Registrar-authorized, unpublished vacancy can be published.'});
    if(new Date(String((r.data as any).closesAt)).getTime()<=Date.now())return res.status(409).json({message:'This vacancy has passed its closing date.'});
    const d=r.data as any;r.status='PUBLISHED';r.data={...d,publishedAt:new Date().toISOString(),publishedBy:req.user!.id,applicationsOpen:true};r.updatedBy=new mongoose.Types.ObjectId(req.user!.id);await r.save();
    await audit(req,'LECTURER_VACANCY_PUBLISHED','lecturer-recruitment',r.id,{authorizedBy:d.authorizedBy});res.json({record:r,message:'Authorized vacancy published.'});
  }catch(e){next(e);}
});
router.post('/vacancies/:id/apply', allowRoles('APPLICANT'), lecturerDocumentUpload, async(req,res,next)=>{
  const uploadedAssets:any[]=[];let applicationPersisted=false;
  try{
    if(!objectId(req.params.id))return res.status(400).json({message:'Invalid vacancy identifier.'});
    const raw=typeof req.body.application==='string'?JSON.parse(req.body.application):req.body;
    const b=z.object({phone:z.string().trim().min(7).max(30),highestQualification:z.string().trim().min(2).max(120),yearsExperience:z.coerce.number().min(0).max(70),coverLetter:z.string().trim().min(30).max(5000),qualifications:z.array(z.string().trim().min(2).max(300)).min(1).max(20),department:z.string().trim().min(2).max(120)}).parse(raw);
    const files=(req.files||{}) as Record<string,Express.Multer.File[]>;
    if(!files.cv?.[0]||!files.highest_degree_certificate?.[0])return res.status(400).json({message:'Upload both your CV and highest qualification certificate. Professional certificate and identity document are optional.'});
    for(const [type,items] of Object.entries(files)){const f=items?.[0];if(f&&!validFileSignature(f))return res.status(400).json({message:`${lecturerDocumentLabels[type as LecturerDocumentType]} does not match its declared file type.`});}

    const vacancy=await RecordModel.findOne({_id:req.params.id,module:'lecturer-recruitment',status:'PUBLISHED','data.kind':'lecturer-vacancy','data.applicationsOpen':true});
    if(!vacancy||new Date(String((vacancy.data as any).closesAt)).getTime()<=Date.now())return res.status(404).json({message:'This vacancy is not open for applications.'});
    const existing=await RecordModel.findOne({module:'lecturer-recruitment','data.kind':'lecturer-candidate','data.vacancyId':String(vacancy._id),'data.applicantId':req.user!.id});
    if(existing)return res.status(409).json({message:'You have already applied for this vacancy.',application:existing});
    const me=await User.findById(req.user!.id).select('fullName email');if(!me)return res.status(404).json({message:'Applicant account not found.'});
    const applicationRef=`LECT-APP-${new mongoose.Types.ObjectId().toString().slice(-10).toUpperCase()}`;
    const documents:any[]=[];
    for(const type of lecturerDocumentTypes){const file=files[type]?.[0];if(!file)continue;const asset=await uploadLecturerDocument(file,req.user!.id,applicationRef,type);uploadedAssets.push({publicId:asset.public_id,resourceType:asset.resource_type|| (file.mimetype==='application/pdf'?'raw':'image'),deliveryType:'authenticated'});documents.push({documentType:type,label:lecturerDocumentLabels[type],publicId:asset.public_id,resourceType:asset.resource_type|| (file.mimetype==='application/pdf'?'raw':'image'),deliveryType:'authenticated',format:asset.format||'',bytes:asset.bytes||file.size,mimeType:file.mimetype,uploadedAt:new Date().toISOString()});}
    const application=await RecordModel.create({module:'lecturer-recruitment',title:`${me.fullName} — ${(vacancy.data as any).position}`,status:'SUBMITTED',ownerId:req.user!.id,reference:applicationRef,data:{kind:'lecturer-candidate',vacancyId:String(vacancy._id),vacancyReference:vacancy.reference,vacancyInitialRecruitmentMode:Boolean((vacancy.data as any).initialRecruitmentMode),applicantId:req.user!.id,applicantName:me.fullName,applicantEmail:me.email,department:String((vacancy.data as any).department),faculty:String((vacancy.data as any).faculty),phone:b.phone,highestQualification:b.highestQualification,yearsExperience:b.yearsExperience,coverLetter:b.coverLetter,qualifications:b.qualifications,documents,documentChecklist:{cv:documents.some(d=>d.documentType==='cv'),highest_degree_certificate:documents.some(d=>d.documentType==='highest_degree_certificate'),professional_certificate:documents.some(d=>d.documentType==='professional_certificate'),identity_document:documents.some(d=>d.documentType==='identity_document')},reviewHistory:[],submittedAt:new Date().toISOString()},createdBy:req.user!.id,updatedBy:req.user!.id});applicationPersisted=true;
    await audit(req,'LECTURER_APPLICATION_SUBMITTED','lecturer-recruitment',application.id,{vacancyId:String(vacancy._id),documentCount:documents.length});res.status(201).json({application:sanitizeLecturerApplication(application),message:'Lecturer application and supporting documents submitted securely. Files are stored in Cloudinary; MongoDB stores document references and metadata.'});
  }catch(e){if(!applicationPersisted)await Promise.allSettled(uploadedAssets.map(asset=>destroyCloudinaryAsset(asset)));next(e);}
});
router.get('/applications/mine', allowRoles('APPLICANT','LECTURER','LECTURER_HOD'), async(req,res,next)=>{
  try{const query:any={module:'lecturer-recruitment','data.kind':'lecturer-candidate'};if(req.user!.role==='APPLICANT')query['data.applicantId']=req.user!.id;else query['data.lecturerUserId']=req.user!.id;const applications=await RecordModel.find(query).sort({createdAt:-1}).limit(100).lean();res.json({applications:applications.map(sanitizeLecturerApplication)});}catch(e){next(e);}
});
router.get('/applications/review', allowRoles('LECTURER_HOD','REGISTRAR'), async(req,res,next)=>{
  try{const query:any={module:'lecturer-recruitment','data.kind':'lecturer-candidate'};if(req.user!.role==='LECTURER_HOD'){const me=await User.findById(req.user!.id).select('department appointmentDepartment hodScope');const dept=me?.appointmentDepartment||me?.department;if(!me?.hodScope||!dept)return res.status(403).json({message:'Only an appointed HOD with a department scope can review lecturer candidates.'});query['data.department']={$regex:`^${String(dept).replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}$`,$options:'i'};query.status={$in:['ADMIN_CHECKED','SHORTLISTED','INTERVIEWED','NEEDS_INFORMATION']};}const applications=await RecordModel.find(query).sort({createdAt:1}).limit(300).lean();res.json({applications:applications.map(sanitizeLecturerApplication)});}catch(e){next(e);}
});
router.get('/applications/:id/documents/:documentType/download', allowRoles('APPLICANT','LECTURER','LECTURER_HOD','REGISTRAR'), async(req,res,next)=>{
  try{if(!objectId(req.params.id))return res.status(400).json({message:'Invalid application identifier.'});const type=req.params.documentType as LecturerDocumentType;if(!lecturerDocumentTypes.includes(type))return res.status(400).json({message:'Unknown lecturer document type.'});const r=await RecordModel.findOne({_id:req.params.id,module:'lecturer-recruitment','data.kind':'lecturer-candidate'});if(!r)return res.status(404).json({message:'Lecturer application not found.'});const d=r.data as any;if(['APPLICANT','LECTURER'].includes(req.user!.role)&&String(d.applicantId)!==req.user!.id&&String(d.lecturerUserId)!==req.user!.id)return res.status(403).json({message:'You can only access documents from your own application.'});if(req.user!.role==='LECTURER_HOD'){const me=await User.findById(req.user!.id).select('department appointmentDepartment hodScope');const dept=me?.appointmentDepartment||me?.department;if(!me?.hodScope||!dept||String(d.department).toLowerCase()!==String(dept).toLowerCase())return res.status(403).json({message:'This application is outside your appointed department.'});if(!['ADMIN_CHECKED','SHORTLISTED','INTERVIEWED','RECOMMENDED','NOT_RECOMMENDED','NEEDS_INFORMATION'].includes(r.status))return res.status(403).json({message:'The application has not reached departmental review.'});}if(req.user!.role==='SUPER_ADMIN'&&!['SUBMITTED','ADMIN_CHECKED','NEEDS_INFORMATION','SHORTLISTED','INTERVIEWED','RECOMMENDED','NOT_RECOMMENDED'].includes(r.status))return res.status(403).json({message:'This application is not available for administrative review.'});const doc=(d.documents||[]).find((x:any)=>x.documentType===type);if(!doc)return res.status(404).json({message:'This document was not uploaded with the application.'});configureLecturerCloudinary();const expires=Math.floor(Date.now()/1000)+300;const url=cloudinary.utils.private_download_url(doc.publicId,doc.format|| (doc.resourceType==='raw'?'pdf':'jpg'),{resource_type:doc.resourceType||'raw',type:'authenticated',expires_at:expires} as any);await audit(req,'LECTURER_APPLICATION_DOCUMENT_ACCESSED','lecturer-recruitment',r.id,{documentType:type});res.json({url,expiresAt:new Date(expires*1000).toISOString(),label:doc.label});}catch(e){next(e);}
});

router.post('/applications/:id/admin-check', allowRoles('SUPER_ADMIN'), async(req,res,next)=>{
  try{if(!objectId(req.params.id))return res.status(400).json({message:'Invalid application identifier.'});const b=z.object({outcome:z.enum(['ADMIN_CHECKED','NEEDS_INFORMATION','SHORTLISTED','NOT_ELIGIBLE']),reason:z.string().trim().min(5).max(2000)}).parse(req.body);const r=await RecordModel.findOne({_id:req.params.id,module:'lecturer-recruitment','data.kind':'lecturer-candidate'});if(!r)return res.status(404).json({message:'Candidate application not found.'});if(!['SUBMITTED','ADMIN_CHECKED','NEEDS_INFORMATION'].includes(r.status))return res.status(409).json({message:'This application is not at the administrative-check stage.'});const d=r.data as any;const history=[...(d.reviewHistory||[]),{stage:'ADMIN_CHECK',outcome:b.outcome,reason:b.reason,reviewerId:req.user!.id,at:new Date().toISOString()}];r.status=b.outcome;r.data={...d,reviewHistory:history,adminCheck:{outcome:b.outcome,reason:b.reason,reviewedBy:req.user!.id,at:new Date().toISOString()}};r.updatedBy=new mongoose.Types.ObjectId(req.user!.id);await r.save();await audit(req,'LECTURER_APPLICATION_ADMIN_CHECK','lecturer-recruitment',r.id,{outcome:b.outcome});await Promise.allSettled([notify(d.applicantId,'Lecturer recruitment update',`Your application status is ${b.outcome.replaceAll('_',' ')}. ${b.reason}`),queueEmailUserIfEnabled(d.applicantId,`lecturer-admin-check:${r.id}:${b.outcome}`,'Lecturer recruitment update',`Your application status is ${b.outcome.replaceAll('_',' ')}. ${b.reason}`)]);res.json({application:sanitizeLecturerApplication(r)});}catch(e){next(e);}
});
router.post('/applications/:id/hod-review', allowRoles('LECTURER_HOD'), async(req,res,next)=>{
  try{if(!objectId(req.params.id))return res.status(400).json({message:'Invalid application identifier.'});const b=z.object({outcome:z.enum(['SHORTLISTED','INTERVIEWED','RECOMMENDED','NOT_RECOMMENDED','NEEDS_INFORMATION']),reason:z.string().trim().min(5).max(2000)}).parse(req.body);const me=await User.findById(req.user!.id).select('department appointmentDepartment hodScope');const dept=me?.appointmentDepartment||me?.department;if(!me?.hodScope||!dept)return res.status(403).json({message:'Only an appointed HOD can review candidates in their department.'});const r=await RecordModel.findOne({_id:req.params.id,module:'lecturer-recruitment','data.kind':'lecturer-candidate','data.department':dept});if(!r)return res.status(404).json({message:'Candidate application not found in your department.'});if(!['ADMIN_CHECKED','SHORTLISTED','INTERVIEWED','NEEDS_INFORMATION'].includes(r.status))return res.status(409).json({message:'The application must pass administrative checks before departmental review.'});const d=r.data as any;const entry={stage:'HOD_REVIEW',outcome:b.outcome,reason:b.reason,reviewerId:req.user!.id,at:new Date().toISOString()};r.status=b.outcome==='RECOMMENDED'?'RECOMMENDED':b.outcome;r.data={...d,hodRecommendation:entry,reviewHistory:[...(d.reviewHistory||[]),entry]};r.updatedBy=new mongoose.Types.ObjectId(req.user!.id);await r.save();await audit(req,'LECTURER_CANDIDATE_HOD_REVIEW','lecturer-recruitment',r.id,{outcome:b.outcome,department:dept});await Promise.allSettled([notify(d.applicantId,'Lecturer recruitment update',`Your application has been reviewed by the department. Status: ${b.outcome.replaceAll('_',' ')}.`),queueEmailUserIfEnabled(d.applicantId,`lecturer-hod-review:${r.id}:${b.outcome}`,'Lecturer recruitment update',`Your application has been reviewed by the department. Status: ${b.outcome.replaceAll('_',' ')}.`)]);res.json({application:sanitizeLecturerApplication(r)});}catch(e){next(e);}
});
router.post('/applications/:id/initial-registrar-review', allowRoles('REGISTRAR'), async(req,res,next)=>{
  try {
    if(!objectId(req.params.id)) return res.status(400).json({message:'Invalid application identifier.'});
    const b=z.object({outcome:z.enum(['RECOMMENDED','NOT_RECOMMENDED','NEEDS_INFORMATION']),reason:z.string().trim().min(5).max(2000)}).parse(req.body);
    const application=await RecordModel.findOne({_id:req.params.id,module:'lecturer-recruitment','data.kind':'lecturer-candidate'});
    if(!application) return res.status(404).json({message:'Candidate application not found.'});
    const data=application.data as any;
    const vacancy=await RecordModel.findOne({_id:data.vacancyId,module:'lecturer-recruitment','data.kind':'lecturer-vacancy'}).lean();
    if(!vacancy || (vacancy.data as any)?.initialRecruitmentMode!==true) return res.status(403).json({message:'Registrar review without an HOD is allowed only for a vacancy explicitly marked as initial recruitment.'});
    const department=String(data.department||'').trim();
    const appointedHod=await User.findOne({role:'LECTURER_HOD',hodScope:true,status:'ACTIVE',$or:[{appointmentDepartment:{$regex:`^${department.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}$`,$options:'i'}},{department:{$regex:`^${department.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}$`,$options:'i'}}]}).select('_id');
    if(appointedHod) return res.status(409).json({message:'An HOD is appointed for this department. The application must follow the normal HOD review process.'});
    if(!['ADMIN_CHECKED','SHORTLISTED','INTERVIEWED','NEEDS_INFORMATION'].includes(application.status)) return res.status(409).json({message:'The application must pass administrative checks before initial Registrar review.'});
    const at=new Date().toISOString();
    const entry={stage:'INITIAL_REGISTRAR_REVIEW_EXCEPTION',outcome:b.outcome,reason:b.reason,reviewerId:req.user!.id,at,exception:'INITIAL_RECRUITMENT_WITHOUT_APPOINTED_HOD'};
    application.status=b.outcome==='RECOMMENDED'?'RECOMMENDED':b.outcome;
    application.data={...data,initialRegistrarReview:entry,reviewHistory:[...(data.reviewHistory||[]),entry]};
    application.updatedBy=new mongoose.Types.ObjectId(req.user!.id); await application.save();
    await audit(req,'LECTURER_INITIAL_RECRUITMENT_REVIEW','lecturer-recruitment',application.id,{outcome:b.outcome,department,exception:'NO_APPOINTED_HOD'});
    await Promise.allSettled([notify(data.applicantId,'Lecturer recruitment update',`Your application has been reviewed by the Registrar under the initial recruitment process. Status: ${b.outcome.replaceAll('_',' ')}.`),queueEmailUserIfEnabled(data.applicantId,`lecturer-initial-review:${application.id}:${b.outcome}`,'Lecturer recruitment update',`Your application has been reviewed by the Registrar under the initial recruitment process. Status: ${b.outcome.replaceAll('_',' ')}. ${b.reason}`)]);
    res.json({application:sanitizeLecturerApplication(application),message:'Initial recruitment review recorded with an explicit no-HOD exception. The Registrar must still make a separate final hiring decision.'});
  } catch(e) { next(e); }
});

router.post('/applications/:id/registrar-decision', allowRoles('REGISTRAR'), async(req,res,next)=>{
  try{if(!objectId(req.params.id))return res.status(400).json({message:'Invalid application identifier.'});const b=z.object({outcome:z.enum(['APPROVED','REJECTED','RETURNED_FOR_REVIEW']),reason:z.string().trim().min(5).max(2000)}).parse(req.body);const r=await RecordModel.findOne({_id:req.params.id,module:'lecturer-recruitment','data.kind':'lecturer-candidate'});if(!r)return res.status(404).json({message:'Candidate application not found.'});if(r.status!=='RECOMMENDED')return res.status(409).json({message:'The Registrar can make a final hiring decision only after a formal HOD recommendation or an explicitly recorded initial-recruitment review.'});const reviewData=r.data as any;if(!reviewData.hodRecommendation&&!reviewData.initialRegistrarReview)return res.status(409).json({message:'A formal review record is required before the final hiring decision.'});const d=r.data as any;const history=[...(d.reviewHistory||[]),{stage:'REGISTRAR_FINAL',outcome:b.outcome,reason:b.reason,reviewerId:req.user!.id,at:new Date().toISOString()}];r.status=b.outcome==='APPROVED'?'OFFERED':b.outcome==='REJECTED'?'REJECTED':'RETURNED_FOR_REVIEW';r.data={...d,registrarDecision:{outcome:b.outcome,reason:b.reason,reviewerId:req.user!.id,at:new Date().toISOString()},reviewHistory:history,offerStatus:b.outcome==='APPROVED'?'PENDING_CANDIDATE_ACCEPTANCE':undefined};r.updatedBy=new mongoose.Types.ObjectId(req.user!.id);await r.save();await audit(req,'LECTURER_RECRUITMENT_REGISTRAR_DECISION','lecturer-recruitment',r.id,{outcome:b.outcome});await notify(d.applicantId,'Lecturer recruitment decision',b.outcome==='APPROVED'?'Your lecturer application has been approved. Please review and accept or decline the offer in your portal.':`Your lecturer application decision is ${b.outcome.replaceAll('_',' ').toLowerCase()}. ${b.reason}`);await queueEmailUserIfEnabled(d.applicantId,`lecturer-decision:${r.id}:${b.outcome}`,'Lecturer recruitment decision',`Your lecturer application decision is ${b.outcome.replaceAll('_',' ').toLowerCase()}. ${b.reason}`);res.json({application:sanitizeLecturerApplication(r)});}catch(e){next(e);}
});
router.post('/applications/:id/offer-response', allowRoles('APPLICANT'), async(req,res,next)=>{
  try{if(!objectId(req.params.id))return res.status(400).json({message:'Invalid application identifier.'});const b=z.object({outcome:z.enum(['ACCEPTED','DECLINED'])}).parse(req.body);const session=await mongoose.startSession();let updated:any;try{await session.withTransaction(async()=>{const r=await RecordModel.findOne({_id:req.params.id,module:'lecturer-recruitment','data.kind':'lecturer-candidate','data.applicantId':req.user!.id}).session(session);if(!r)throw Object.assign(new Error('Your lecturer application was not found.'),{status:404});if(r.status!=='OFFERED'||(r.data as any).offerStatus!=='PENDING_CANDIDATE_ACCEPTANCE')throw Object.assign(new Error('There is no pending offer to respond to.'),{status:409});const d=r.data as any;const now=new Date().toISOString();r.status=b.outcome==='ACCEPTED'?'ACCEPTED_BY_CANDIDATE':'OFFER_DECLINED';r.data={...d,offerStatus:b.outcome,offerRespondedAt:now,reviewHistory:[...(d.reviewHistory||[]),{stage:'CANDIDATE_OFFER_RESPONSE',outcome:b.outcome,at:now}]};r.updatedBy=new mongoose.Types.ObjectId(req.user!.id);await r.save({session});if(b.outcome==='ACCEPTED'){const user=await User.findById(req.user!.id).session(session);if(!user||user.role!=='APPLICANT')throw Object.assign(new Error('Only an applicant account can accept this offer.'),{status:409});if(user.staffId)throw Object.assign(new Error('A Staff ID has already been generated for this account.'),{status:409});user.role='LECTURER';user.department=d.department;user.appointmentDepartment=d.department;user.faculty=d.faculty;user.status='ACTIVE';const seq=await SystemSetting.findOneAndUpdate({key:'lecturer-staff-id-sequence'},{$inc:{'value.next':1}},{new:true,upsert:true,session,setDefaultsOnInsert:true});const n=Number((seq.value as any)?.next||1);const staffId=`CFU/STAFF/${new Date().getFullYear()}/${String(n).padStart(5,'0')}`;user.staffId=staffId;user.staffIdGeneratedAt=new Date();user.mustChangePassword=true;await user.save({session});r.data={...(r.data as any),lecturerUserId:String(user._id),onboardedAt:now,staffId,staffIdGeneratedAt:user.staffIdGeneratedAt};await r.save({session});}updated=r;});}finally{await session.endSession();}await audit(req,'LECTURER_OFFER_RESPONSE','lecturer-recruitment',String(updated._id),{outcome:b.outcome,staffId:b.outcome==='ACCEPTED'?((updated.data as any)?.staffId):undefined});if(b.outcome==='ACCEPTED'){const d=updated.data as any;const targets=await User.find({role:{$in:['SUPER_ADMIN','REGISTRAR']},status:'ACTIVE'}).select('_id email fullName');await Promise.allSettled(targets.flatMap((u:any)=>[notify(String(u._id),'Lecturer offer accepted',`${d.applicantName} accepted the lecturer offer for ${d.department}. Staff ID: ${d.staffId}.`),queueEmailUserIfEnabled(String(u._id),`lecturer-onboarded:${updated._id}:${u._id}`,'Lecturer offer accepted',`${d.applicantName} accepted the lecturer offer for ${d.department}. Staff ID: ${d.staffId}.`)]));}res.json({application:sanitizeLecturerApplication(updated),message:b.outcome==='ACCEPTED'?`Offer accepted. Your Staff ID ${((updated.data as any)?.staffId)||''} has been generated automatically. You must change your password at next sign-in.`:'Offer declined.'});}catch(e){next(e);}
});
