router.post('/academic/:id/hod-review', allowRoles('LECTURER_HOD'), async(req,res,next)=>{
  try{if(!objectId(req.params.id))return res.status(400).json({message:'Invalid academic submission identifier.'});const b=z.object({outcome:z.enum(['APPROVED','RETURNED_FOR_CORRECTION','RECOMMENDED_FOR_REGISTRAR']),reason:z.string().trim().min(5).max(2000)}).parse(req.body);const me=await User.findById(req.user!.id).select('department appointmentDepartment hodScope');const dept=me?.appointmentDepartment||me?.department;if(!me?.hodScope||!dept)return res.status(403).json({message:'Only an appointed HOD can review departmental academic submissions.'});const r=await RecordModel.findOne({_id:req.params.id,module:'lecturer-workflow',status:'SUBMITTED_FOR_REVIEW'});if(!r)return res.status(404).json({message:'Pending lecturer submission not found.'});const d=r.data as any;if(d.department&&String(d.department).toLowerCase()!==String(dept).toLowerCase())return res.status(403).json({message:'This submission is outside your appointed department.'});if(d.stage==='course-assignment'&&b.outcome==='RECOMMENDED_FOR_REGISTRAR')return res.status(400).json({message:'Course assignments are approved or returned by the HOD; Registrar recommendation is not used for this action.'});if(d.stage==='assessment-results'&&b.outcome==='APPROVED')return res.status(400).json({message:'HOD review recommends results for the Registrar; it does not publish official results.'});const now=new Date().toISOString();const history=[...(d.hodReviewHistory||[]),{outcome:b.outcome,reason:b.reason,reviewerId:req.user!.id,department:dept,at:now}];r.status=b.outcome==='RETURNED_FOR_CORRECTION'?'RETURNED_FOR_CORRECTION':b.outcome==='APPROVED'?'APPROVED':'RECOMMENDED';r.data={...d,department:d.department||dept,hodReview:{outcome:b.outcome,reason:b.reason,reviewerId:req.user!.id,department:dept,at:now},hodReviewHistory:history,officialPublication:false};r.updatedBy=new mongoose.Types.ObjectId(req.user!.id);await r.save();let registrarRecord:any=null;if(d.stage==='assessment-results'&&b.outcome==='RECOMMENDED_FOR_REGISTRAR'){const academicRecord=await RecordModel.create({module:'academics',title:d.title||`Result ${d.courseCode}`,status:'RECOMMENDED',ownerId:d.submittedBy||r.ownerId,reference:`ASSESS-${r.id}`,data:{kind:'assessment-result',sourceLecturerSubmissionId:String(r._id),lecturerId:d.submittedBy||String(r.ownerId||''),courseCode:d.courseCode,session:d.session,semester:d.semester,studentReference:d.studentReference,score:d.score,department:dept,hodRecommendation:{reason:b.reason,reviewerId:req.user!.id,at:now},officialPublication:false},createdBy:req.user!.id,updatedBy:req.user!.id});registrarRecord=await RecordModel.create({module:'registrar',title:`Final result approval — ${d.courseCode}`,status:'PENDING_REVIEW',reference:`RESULT-DECISION-${academicRecord.id}`,data:{category:'result-approval',details:`HOD recommendation: ${b.reason}`,linkedRecordId:String(academicRecord._id),department:dept,courseCode:d.courseCode,session:d.session,semester:d.semester,sourceLecturerSubmissionId:String(r._id),decisionHistory:[]},createdBy:req.user!.id,updatedBy:req.user!.id});const registrars=await User.find({role:'REGISTRAR',status:'ACTIVE'}).select('_id');await Promise.allSettled(registrars.map(u=>notify(String(u._id),'Result approval required',`HOD recommended result submission ${d.courseCode} for final review. Open Registrar workspace record ${registrarRecord.id}.`)));}await audit(req,'HOD_ACADEMIC_SUBMISSION_REVIEWED','lecturer-workflow',r.id,{outcome:b.outcome,department:dept,registrarRecordId:registrarRecord?String(registrarRecord._id):null});if(d.submittedBy){await notify(String(d.submittedBy),'Lecturer submission reviewed',`Your ${d.stage} submission for ${d.courseCode} was ${b.outcome.replaceAll('_',' ').toLowerCase()}. ${b.reason}`);}res.json({record:r,registrarRecord,message:registrarRecord?'HOD recommendation recorded and a canonical academic result record created for the Registrar review queue.':`HOD review recorded: ${b.outcome}.`});}catch(e){next(e);}
});

// Course materials use authenticated Cloudinary assets; MongoDB stores only references and metadata.
const courseMaterialUpload=multer({storage:multer.memoryStorage(),limits:{fileSize:15*1024*1024,files:1},fileFilter:(_req,file,cb)=>file.mimetype==='application/pdf'?cb(null,true):cb(new Error('Course materials must be PDF files up to 15 MB.'))}).single('file');
router.post('/materials',allowRoles(...teachingRoles),courseMaterialUpload,async(req,res,next)=>{let asset:any=null;let materialPersisted=false;try{const b=z.object({title:z.string().trim().min(3).max(180),courseCode:z.string().trim().min(2).max(20),session:z.string().trim().min(4).max(30),description:z.string().trim().max(1500).optional()}).parse(req.body);const file=req.file;if(!file)return res.status(400).json({message:'Choose a PDF course material.'});if(!validFileSignature(file))return res.status(400).json({message:'The selected file is not a valid PDF.'});const courseCode=b.courseCode.toUpperCase();const assignment=await RecordModel.findOne({module:'lecturer-workflow',ownerId:req.user!.id,status:'APPROVED','data.stage':'course-assignment','data.courseCode':{$regex:`^${courseCode}$`,$options:'i'},'data.session':b.session});if(!assignment)return res.status(403).json({message:'Upload materials only for a course formally assigned to you.'});configureLecturerCloudinary();asset=await new Promise<any>((resolve,reject)=>{const stream=cloudinary.uploader.upload_stream({folder:`crestfield/private-course-materials/${req.user!.id}`,resource_type:'raw',type:'authenticated',public_id:`material-${randomUUID()}`,format:'pdf',overwrite:false},(error,result)=>error||!result?reject(error||new Error('Cloudinary upload failed.')):resolve(result));stream.end(file.buffer);});const now=new Date().toISOString();const record=await RecordModel.create({module:'academics',title:b.title,status:'PUBLISHED',ownerId:req.user!.id,reference:`MATERIAL-${new mongoose.Types.ObjectId().toString().toUpperCase()}`,data:{kind:'course-material',courseCode,session:b.session,description:b.description||'',publicId:asset.public_id,resourceType:'raw',deliveryType:'authenticated',format:'pdf',bytes:asset.bytes||file.size,uploadedBy:req.user!.id,uploadedAt:now},createdBy:req.user!.id,updatedBy:req.user!.id});materialPersisted=true;await audit(req,'LECTURER_COURSE_MATERIAL_UPLOADED','academics',record.id,{courseCode,session:b.session});res.status(201).json({material:{_id:String(record._id),title:record.title,courseCode,session:b.session,description:b.description||'',bytes:asset.bytes||file.size,uploadedAt:now},message:'Material uploaded to private Cloudinary storage.'});}catch(e){if(asset?.public_id&&!materialPersisted)await destroyCloudinaryAsset({publicId:asset.public_id,resourceType:'raw',deliveryType:'authenticated'}).catch(()=>undefined);next(e);}});
router.get('/materials/mine',allowRoles(...teachingRoles),async(req,res,next)=>{try{const rows=await RecordModel.find({module:'academics',ownerId:req.user!.id,'data.kind':'course-material'}).sort({createdAt:-1}).limit(300).lean();res.json({materials:rows.map((r:any)=>({_id:String(r._id),title:r.title,courseCode:r.data.courseCode,session:r.data.session,description:r.data.description||'',bytes:r.data.bytes,uploadedAt:r.data.uploadedAt}))});}catch(e){next(e);}});
router.get('/materials/student',allowRoles('REGISTERED_STUDENT','STUDENT'),async(req,res,next)=>{try{const regs=await RecordModel.find({module:'student-workflow','data.stage':'course-registration',status:{$in:['APPROVED','REGISTERED','COMPLETED']},$or:[{'data.studentId':req.user!.id},{ownerId:req.user!.id}]}).select('data').lean();const enrolled=new Set<string>();const sessions=new Set<string>();for(const r of regs){const d:any=r.data||{};const courses=Array.isArray(d.courseCodes)?d.courseCodes:Array.isArray(d.courses)?d.courses:[];for(const c of courses)enrolled.add(String(typeof c==='string'?c:c.code||c.courseCode||'').toUpperCase());if(d.session)sessions.add(String(d.session));}if(!enrolled.size||!sessions.size)return res.json({materials:[]});const q:any={module:'academics',status:'PUBLISHED','data.kind':'course-material','data.courseCode':{$in:[...enrolled]},'data.session':{$in:[...sessions]}};const rows=await RecordModel.find(q).sort({createdAt:-1}).limit(500).lean();res.json({materials:rows.map((r:any)=>({_id:String(r._id),title:r.title,courseCode:r.data.courseCode,session:r.data.session,description:r.data.description||'',uploadedAt:r.data.uploadedAt}))});}catch(e){next(e);}});
router.get('/materials/:id/download',allowRoles('LECTURER','LECTURER_HOD','REGISTRAR','REGISTERED_STUDENT','STUDENT'),async(req,res,next)=>{try{if(!objectId(req.params.id))return res.status(400).json({message:'Invalid material identifier.'});const r=await RecordModel.findOne({_id:req.params.id,module:'academics',status:'PUBLISHED','data.kind':'course-material'});if(!r)return res.status(404).json({message:'Course material not found.'});const d:any=r.data;if(['REGISTERED_STUDENT','STUDENT'].includes(req.user!.role)){const regs=await RecordModel.find({module:'student-workflow','data.stage':'course-registration',status:{$in:['APPROVED','REGISTERED','COMPLETED']},$or:[{'data.studentId':req.user!.id},{ownerId:req.user!.id}]}).select('data').lean();const allowed=regs.some((x:any)=>{const rd:any=x.data||{};const courses=Array.isArray(rd.courseCodes)?rd.courseCodes:Array.isArray(rd.courses)?rd.courses:[];return Boolean(rd.session)&&String(rd.session)===String(d.session)&&courses.some((c:any)=>String(typeof c==='string'?c:c.code||c.courseCode||'').toUpperCase()===String(d.courseCode).toUpperCase());});if(!allowed)return res.status(403).json({message:'You are not registered for this course/session.'});}else if(['LECTURER','LECTURER_HOD'].includes(req.user!.role)){const assigned=await RecordModel.find({module:'lecturer-workflow',ownerId:req.user!.id,status:'APPROVED','data.stage':'course-assignment','data.session':d.session}).select('data.courseCode').lean();if(!assigned.some((a:any)=>String((a.data as any)?.courseCode||'').toUpperCase()===String(d.courseCode).toUpperCase()))return res.status(403).json({message:'You are not assigned to this course.'});}configureLecturerCloudinary();const exp=Math.floor(Date.now()/1000)+300;const url=cloudinary.utils.private_download_url(d.publicId,'pdf',{resource_type:'raw',type:'authenticated',expires_at:exp} as any);await audit(req,'COURSE_MATERIAL_ACCESSED','academics',String(r._id),{courseCode:d.courseCode,session:d.session});res.json({url,expiresAt:new Date(exp*1000).toISOString()});}catch(e){next(e);}});

// New-course proposals are separate from course-assignment requests. They cannot enter the official catalogue until the Registrar approves them.
router.post('/courses/proposals', allowRoles(...teachingRoles), async(req,res,next)=>{
  try{
    const b=z.object({courseTitle:z.string().trim().min(4).max(180),suggestedCode:z.string().trim().max(20).optional().default(''),department:z.string().trim().min(2).max(120),faculty:z.string().trim().min(2).max(120),level:z.string().trim().min(1).max(40),creditUnits:z.coerce.number().int().min(1).max(12),description:z.string().trim().min(30).max(5000),objectives:z.string().trim().min(20).max(4000),rationale:z.string().trim().min(30).max(4000),prerequisites:z.string().trim().max(1000).optional().default('')}).parse(req.body);
    const me=await User.findById(req.user!.id).select('fullName department faculty appointmentDepartment');if(!me)return res.status(404).json({message:'Lecturer account not found.'});
    const assignedDepartment=String(me.appointmentDepartment||me.department||'').trim();
    if(!assignedDepartment)return res.status(403).json({message:'Your lecturer account must have an assigned department before you can propose a course.'});
    if(assignedDepartment.toLowerCase()!==b.department.toLowerCase())return res.status(403).json({message:'You can propose courses only for your assigned department.'});
    const normalizedCode=b.suggestedCode.trim().toUpperCase();
    if(normalizedCode){const duplicate=await RecordModel.findOne({module:'registrar','data.category':'course','data.courseCode':normalizedCode,status:{$in:['APPROVED','PUBLISHED','ACTIVE']}}).select('_id');if(duplicate)return res.status(409).json({message:'That course code already exists in the official catalogue. Suggest a different code or leave it for Registrar allocation.'});}
    const ref=`COURSE-PROP-${new mongoose.Types.ObjectId().toString().slice(-10).toUpperCase()}`;
    const proposal=await RecordModel.create({module:'lecturer-course-proposals',title:b.courseTitle,status:'SUBMITTED',ownerId:req.user!.id,reference:ref,data:{kind:'new-course-proposal',...b,suggestedCode:normalizedCode,proposedBy:req.user!.id,proposerName:me.fullName,department:b.department,faculty:b.faculty,reviewHistory:[{stage:'LECTURER_SUBMISSION',outcome:'SUBMITTED',reviewerId:req.user!.id,at:new Date().toISOString()}],officialCourseCreated:false,submittedAt:new Date().toISOString()},createdBy:req.user!.id,updatedBy:req.user!.id});
    await audit(req,'NEW_COURSE_PROPOSAL_SUBMITTED','lecturer-course-proposals',proposal.id,{department:b.department,suggestedCode:normalizedCode||null});
    const hods=await User.find({role:'LECTURER_HOD',status:'ACTIVE',hodScope:true,$or:[{appointmentDepartment:b.department},{department:b.department}]}).select('_id').lean();
    await Promise.allSettled(hods.map(async h=>{await notify(String(h._id),'New course proposal awaiting HOD review',`${me.fullName} proposed “${b.courseTitle}” for ${b.department}. Review the proposal in your HOD portal.`);await queueEmailUserIfEnabled(String(h._id),`course-proposal:${proposal.id}:hod:${h._id}`,'New course proposal awaiting HOD review',`${me.fullName} proposed “${b.courseTitle}” for ${b.department}. Review the proposal in your HOD portal.`);}));
    res.status(201).json({proposal,message:'New-course proposal submitted. It is not an official course and cannot be registered until the Registrar approves it.'});
  }catch(e){next(e);}
});
router.get('/courses/proposals/mine',allowRoles(...teachingRoles),async(req,res,next)=>{try{const proposals=await RecordModel.find({module:'lecturer-course-proposals','data.kind':'new-course-proposal',ownerId:req.user!.id}).sort({createdAt:-1}).limit(200).lean();res.json({proposals});}catch(e){next(e);}});
router.get('/courses/proposals/review',allowRoles('LECTURER_HOD','REGISTRAR'),async(req,res,next)=>{try{const q:any={module:'lecturer-course-proposals','data.kind':'new-course-proposal'};if(req.user!.role==='LECTURER_HOD'){const me=await User.findById(req.user!.id).select('department appointmentDepartment hodScope');const dept=me?.appointmentDepartment||me?.department;if(!me?.hodScope||!dept)return res.status(403).json({message:'Only an appointed HOD with department scope can review course proposals.'});q['data.department']={$regex:`^${String(dept).replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}$`,$options:'i'};q['data.proposedBy']={$ne:req.user!.id};q.status={$in:['SUBMITTED','HOD_RECOMMENDED','HOD_NOT_RECOMMENDED','NEEDS_INFORMATION']};}const proposals=await RecordModel.find(q).sort({createdAt:1}).limit(300).lean();res.json({proposals});}catch(e){next(e);}});
router.post('/courses/proposals/:id/hod-review',allowRoles('LECTURER_HOD'),async(req,res,next)=>{try{if(!objectId(req.params.id))return res.status(400).json({message:'Invalid proposal identifier.'});const b=z.object({outcome:z.enum(['RECOMMEND','DO_NOT_RECOMMEND','RETURN_FOR_INFORMATION']),reason:z.string().trim().min(5).max(2000)}).parse(req.body);const me=await User.findById(req.user!.id).select('department appointmentDepartment hodScope');const dept=me?.appointmentDepartment||me?.department;if(!me?.hodScope||!dept)return res.status(403).json({message:'Only an appointed HOD with department scope can review proposals.'});const r=await RecordModel.findOne({_id:req.params.id,module:'lecturer-course-proposals','data.kind':'new-course-proposal','data.department':{$regex:`^${String(dept).replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}$`,$options:'i'},'data.proposedBy':{$ne:req.user!.id}});if(!r)return res.status(404).json({message:'Proposal not found in your appointed department, or you cannot review your own proposal.'});if(!['SUBMITTED','NEEDS_INFORMATION'].includes(r.status))return res.status(409).json({message:'This proposal is not awaiting HOD review.'});const outcome=b.outcome==='RECOMMEND'?'HOD_RECOMMENDED':b.outcome==='DO_NOT_RECOMMEND'?'HOD_NOT_RECOMMENDED':'NEEDS_INFORMATION';const d:any=r.data;r.status=outcome;r.data={...d,hodReview:{outcome:b.outcome,reason:b.reason,reviewerId:req.user!.id,at:new Date().toISOString()},reviewHistory:[...(d.reviewHistory||[]),{stage:'HOD_REVIEW',outcome,reason:b.reason,reviewerId:req.user!.id,at:new Date().toISOString()}]};r.updatedBy=new mongoose.Types.ObjectId(req.user!.id);await r.save();await audit(req,'NEW_COURSE_PROPOSAL_HOD_REVIEW','lecturer-course-proposals',r.id,{outcome});await Promise.allSettled([notify(String(d.proposedBy),'Update on your new-course proposal',`Your proposal “${r.title}” has received the HOD review: ${outcome.replaceAll('_',' ')}. ${b.reason}`),queueEmailUserIfEnabled(String(d.proposedBy),`course-proposal:${r.id}:hod:${outcome}`,'Update on your new-course proposal',`Your proposal “${r.title}” has received the HOD review: ${outcome.replaceAll('_',' ')}. ${b.reason}`)]);res.json({proposal:r,message:'HOD review recorded. The Registrar retains the final institutional decision.'});}catch(e){next(e);}});
router.post('/courses/proposals/:id/registrar-decision',allowRoles('REGISTRAR'),async(req,res,next)=>{try{if(!objectId(req.params.id))return res.status(400).json({message:'Invalid proposal identifier.'});const b=z.object({decision:z.enum(['APPROVE','REJECT','RETURN_FOR_INFORMATION']),reason:z.string().trim().min(5).max(2000),officialCourseCode:z.string().trim().min(2).max(20).optional()}).parse(req.body);const r=await RecordModel.findOne({_id:req.params.id,module:'lecturer-course-proposals','data.kind':'new-course-proposal'});if(!r)return res.status(404).json({message:'Course proposal not found.'});if(!['HOD_RECOMMENDED','HOD_NOT_RECOMMENDED','NEEDS_INFORMATION'].includes(r.status))return res.status(409).json({message:'A recorded HOD review is required before the Registrar can decide this proposal.'});const d:any=r.data;let officialCourse:any=null;if(b.decision==='APPROVE'){const code=String(b.officialCourseCode||d.suggestedCode||'').trim().toUpperCase();if(!code)return res.status(400).json({message:'Provide an official course code before approving this proposal.'});const duplicate=await RecordModel.findOne({module:'registrar','data.category':'course','data.courseCode':code,status:{$in:['APPROVED','PUBLISHED','ACTIVE']}}).select('_id');if(duplicate)return res.status(409).json({message:'That course code is already used by an official course.'});officialCourse=await RecordModel.create({module:'registrar',title:d.courseTitle,status:'APPROVED',reference:`COURSE-${code}`,data:{category:'course',courseCode:code,code,courseTitle:d.courseTitle,department:d.department,faculty:d.faculty,level:d.level,creditUnits:d.creditUnits,description:d.description,objectives:d.objectives,rationale:d.rationale,prerequisites:d.prerequisites||'',sourceProposalId:String(r._id),approvedBy:req.user!.id,approvedAt:new Date().toISOString(),approvalSource:'lecturer-course-proposal'},createdBy:req.user!.id,updatedBy:req.user!.id});}
const status=b.decision==='APPROVE'?'APPROVED':b.decision==='REJECT'?'REJECTED':'NEEDS_INFORMATION';r.status=status;r.data={...d,registrarDecision:{decision:b.decision,reason:b.reason,reviewerId:req.user!.id,at:new Date().toISOString(),officialCourseId:officialCourse?String(officialCourse._id):null,officialCourseCode:officialCourse?.data?.courseCode||null},officialCourseCreated:Boolean(officialCourse),reviewHistory:[...(d.reviewHistory||[]),{stage:'REGISTRAR_DECISION',outcome:status,reason:b.reason,reviewerId:req.user!.id,at:new Date().toISOString()}]};r.updatedBy=new mongoose.Types.ObjectId(req.user!.id);await r.save();await audit(req,'NEW_COURSE_PROPOSAL_REGISTRAR_DECISION','lecturer-course-proposals',r.id,{decision:b.decision,officialCourseId:officialCourse?String(officialCourse._id):null});const message=b.decision==='APPROVE'?`Your course proposal “${r.title}” was approved. Official course code: ${officialCourse.data.courseCode}. The course is approved in the catalogue but is not automatically assigned to a lecturer.`:b.decision==='REJECT'?`Your course proposal “${r.title}” was rejected. ${b.reason}`:`Your course proposal “${r.title}” was returned for information. ${b.reason}`;await Promise.allSettled([notify(String(d.proposedBy),'Registrar decision on course proposal',message),queueEmailUserIfEnabled(String(d.proposedBy),`course-proposal:${r.id}:registrar:${status}`,'Registrar decision on course proposal',message)]);res.json({proposal:r,officialCourse,message});}catch(e){next(e);}});

// Attendance belongs only to Lecturer and Student portals. HOD/Registrar receive no attendance-monitoring endpoints.
router.post('/attendance', allowRoles(...teachingRoles), async(req,res,next)=>{
  try{
    const b=z.object({courseCode:z.string().trim().min(2).max(20),session:z.string().trim().min(4).max(30),semester:z.string().trim().min(2).max(30),classDate:z.string().datetime(),records:z.array(z.object({studentId:z.string().refine(objectId),status:z.enum(['PRESENT','ABSENT','LATE','EXCUSED'])})).min(1).max(300),note:z.string().trim().max(1000).optional()}).parse(req.body);
    const courseCode=b.courseCode.toUpperCase();const assignment=await RecordModel.findOne({module:'lecturer-workflow',ownerId:req.user!.id,status:'APPROVED','data.stage':'course-assignment','data.courseCode':{$regex:`^${courseCode}$`,$options:'i'},'data.session':b.session});if(!assignment)return res.status(403).json({message:'Attendance can be recorded only for an approved course assigned to your lecturer account for this session.'});
    const ids=[...new Set(b.records.map(x=>x.studentId))];const students=await User.find({_id:{$in:ids},role:{$in:['REGISTERED_STUDENT','STUDENT']},status:'ACTIVE'}).select('_id fullName matricNumber department');if(students.length!==ids.length)return res.status(400).json({message:'Every attendance entry must reference an active registered student.'});
    const created=[];for(const item of b.records){const student=students.find(s=>String(s._id)===item.studentId)!;const prior=await RecordModel.findOne({module:'academics',ownerId:req.user!.id,'data.kind':'attendance','data.studentId':item.studentId,'data.courseCode':courseCode,'data.session':b.session,'data.semester':b.semester,'data.classDate':b.classDate});if(prior){prior.data={...(prior.data as any),status:item.status,note:b.note||'',updatedAttendanceAt:new Date().toISOString(),updatedBy:req.user!.id};prior.updatedBy=new mongoose.Types.ObjectId(req.user!.id);await prior.save();created.push(prior);}else created.push(await RecordModel.create({module:'academics',title:`Attendance ${courseCode} — ${student.fullName}`,status:'PUBLISHED',ownerId:req.user!.id,reference:`ATT-${courseCode}-${item.studentId}-${new Date(b.classDate).toISOString().slice(0,10)}-${new mongoose.Types.ObjectId().toString().slice(-5)}`,data:{kind:'attendance',studentId:item.studentId,studentName:student.fullName,matricNumber:student.matricNumber||'',lecturerId:req.user!.id,courseCode,session:b.session,semester:b.semester,classDate:b.classDate,status:item.status,note:b.note||'',publishedAt:new Date().toISOString()},createdBy:req.user!.id,updatedBy:req.user!.id}));}
    await audit(req,'LECTURER_ATTENDANCE_RECORDED','academics',String(assignment._id),{courseCode,session:b.session,semester:b.semester,studentCount:b.records.length,classDate:b.classDate});res.status(201).json({count:created.length,records:created,message:'Attendance saved. Students can view their own records in the Student Portal.'});
  }catch(e){next(e);}
});
router.get('/attendance/mine', allowRoles('REGISTERED_STUDENT','STUDENT'), async(req,res,next)=>{
  try{const records=await RecordModel.find({module:'academics','data.kind':'attendance','data.studentId':req.user!.id,status:'PUBLISHED'}).sort({'data.classDate':-1}).limit(1000).select('title data createdAt').lean();const grouped=new Map<string,any>();for(const r of records){const d=r.data as any;const key=`${d.courseCode}::${d.session}::${d.semester}`;if(!grouped.has(key))grouped.set(key,{courseCode:d.courseCode,session:d.session,semester:d.semester,total:0,present:0,absent:0,late:0,excused:0,records:[]});const g=grouped.get(key);g.total++;const st=String(d.status||'').toLowerCase();if(st==='present')g.present++;if(st==='absent')g.absent++;if(st==='late')g.late++;if(st==='excused')g.excused++;g.records.push({date:d.classDate,status:d.status,note:d.note||''});}res.json({records,byCourse:[...grouped.values()].map(g=>({...g,percentage:g.total?Number(((g.present/g.total)*100).toFixed(1)):0}))});}catch(e){next(e);}
});
router.get('/attendance/course/:courseCode', allowRoles(...teachingRoles), async(req,res,next)=>{
  try{const courseCode=String(req.params.courseCode).toUpperCase();const session=String(req.query.session||'');const assignment=await RecordModel.findOne({module:'lecturer-workflow',ownerId:req.user!.id,status:'APPROVED','data.stage':'course-assignment','data.courseCode':{$regex:`^${courseCode}$`,$options:'i'},'data.session':session});if(!assignment)return res.status(403).json({message:'You may view attendance only for an approved course assigned to you.'});const records=await RecordModel.find({module:'academics',ownerId:req.user!.id,'data.kind':'attendance','data.courseCode':courseCode,'data.session':session}).sort({'data.classDate':-1}).limit(1000).lean();res.json({records});}catch(e){next(e);}
});

export default router;
